public object DeserializeData(byte[] data)
{
    // Use a safe deserializer with type restrictions, e.g., DataContractSerializer or JsonSerializer
    // Example using DataContractSerializer with a known type list:
    var settings = new DataContractSerializerSettings { KnownTypes = new List<Type> { typeof(ExpectedType) } };
    var serializer = new DataContractSerializer(typeof(object), settings);
    using (MemoryStream ms = new MemoryStream(data))
    {
        return serializer.ReadObject(ms);
    }
}

